WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_111'), 'A help-center article has 1,000 words. The chunker uses windows of 200 words with an overlap of 50 words, and it stops as soon as a window reaches the last word. How many chunks does it produce?', 'single_choice'::question_type, 'Each window starts 200 - 50 = 150 words after the previous one: at words 0, 150, 300, 450, 600, 750 and 900. The window starting at 750 ends at word 949, which is not the last word, so one more window starts at 900 and covers words 900-999. That window reaches the last word, so the chunker stops: 7 chunks, and 6 x 50 = 300 words are embedded twice. Overlap is not free: it adds roughly overlap / (size - overlap) extra chunks.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_111') AND order_index = 1)
    RETURNING id
)
