    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_111'), 'Why do production RAG pipelines add overlap between chunks? (Select all that apply.)', 'multiple_choice'::question_type, 'Overlap means the words around every boundary appear in two chunks. A fact shorter than the overlap - "refunds are processed within 30 days" - is therefore whole in at least one chunk instead of being split across two, and a question about text near a boundary can match a chunk that contains its context on both sides. Overlap does the opposite of saving space: it adds chunks (and embedding cost), and it does nothing about the model''s token limit - the window size still has to stay below it.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_111') AND order_index = 2)
    RETURNING id
)
