UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211'), 'Two help articles both mention "refund" twice. Article A has 60 words, article B has 600 words; the corpus average is 150 words. With the default b = 0.75, how does BM25 score the term "refund" for them?', 'single_choice'::question_type, 'b controls length normalisation. The denominator of the term-frequency part grows with |D| / avgdl, so the same two occurrences are worth more in the short article (60 / 150 = 0.4) than in the long one (600 / 150 = 4): in a short text, two mentions say much more about what it is about. With b = 0 both would score the same; with b = 1 the length effect is at its strongest.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Equally: BM25 only counts occurrences.', false),
        ('Higher for A: the same occurrences count for more in a shorter document.', true),
        ('Higher for B: longer documents are more likely to be thorough.', false),
        ('It depends on k1 only; b affects the IDF.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211'), 'Which statements about BM25 are true? (Select all that apply.)', 'multiple_choice'::question_type, 'The term-frequency part f * (k1 + 1) / (f + k1 * ...) saturates: it grows quickly for the first occurrences and flattens towards k1 + 1, so the tenth occurrence adds far less than the second - keyword stuffing stops paying off. With k1 = 0 the part is f / f = 1 for any f > 0, so a term only counts by presence. With the +1 inside the logarithm, IDF stays positive even for a term found in every document, and a query term found in no document never contributes because f = 0 everywhere. Doubling a document''s length lowers, not raises, its score for the same occurrences.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211') AND order_index = 2)
    RETURNING id
)
