vector = embed(chunk.text)
length = math.hypot(*vector)
index.add(chunk.id, [x / length for x in vector])

# search.py - the query vector is normalized the same way
score = sum(x * y for x, y in zip(query_vector, chunk_vector))

Statement: "search.py ranks chunks differently from cosine similarity, so it must also divide by both vector lengths at query time."', 'single_choice'::question_type, 'False. Both vectors already have length 1, so |q| * |v| = 1 and the dot product equals the cosine: same scores, same ranking. Normalizing once at write time and using the cheaper dot product at query time is the usual design (it is what an inner-product index expects). The misconception: "dot product is always the bug". The bug is a dot product over vectors whose lengths differ - check the norms in the index, not the formula alone.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_fix_py_rag_232 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_py_rag_232', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-2-3' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-unnormalized-cosine', 'Spot the AI Mistake: cosine similarity without normalization', 'The support assistant''s team sent this request to an AI assistant: "Write vector_search(query, chunks, top) for our support assistant. Rank the chunks by cosine similarity between their embedding and the query embedding and return the best `top` as {''id'', ''score''}, with the score rounded to 4 decimals. Highest score first, ties by id. A chunk whose vector is all zeros has no direction: skip it. If the query vector is all zeros, return an empty list." The AI''s code passed review and the public tests, which use the unit-length vectors of the embeddings API. Since the PDF import stores one vector per page (the sum of its paragraph vectors), "sync error E1042" returns the 4,000-word refund policy first, with a score of 4.92. Fix vector_search() so that it does what the request says: score = dot(query, vector) / (|query| * |vector|) rounded to 4 decimals, zero vectors skipped, an all-zero query returns [], sorted by score descending then id ascending, at most `top` results. All vectors in one call have the same dimension. The public tests pass on the AI''s code; the hidden tests use vectors of different lengths.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
