-- challenge chal_fix_py_rag_332 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_py_rag_332', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-3-3' AND is_deleted = false LIMIT 1), 'citation-check', 'Fix the citation check that passed the wrong answer', 'check_citations(context, answer) is the guard that runs after every answer of the support assistant. The context is the packed prompt context (lines "[n] text", where n is the source''s citation number; two chunks of one source share n). In the "Right Docs, Wrong Answer?" incident it reported "2/2 sentences supported" for "The refund arrives within 30 days [4]." although source [4] never mentions 30 days. Support has found more: it accepts "3 days [1]" when source 1 says 30 days, and it flags correct sentences when the number is in the first of two chunks from the same source. Fix it so that, for each sentence of the answer (numbered from 1, split by the given split_sentences()), with citations = the [n] markers and facts = the numbers matched by NUMBER in the sentence without its markers: the problem is "unknown_source" if a cited n has no line in the context; otherwise "uncited" if there are facts but no citation; otherwise "unsupported" if a fact is not one of the numbers found in all lines of the cited sources, compared as whole numbers. Return one {"sentence", "problem"} per sentence with a problem, in sentence order; an empty answer returns [].', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
